import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Backups","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/sauvegardes.md","filePath":"src/en/guide/admin/sauvegardes.md"}'),s={name:"en/guide/admin/sauvegardes.md"};function i(r,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h1><p>A backup is a copy of everything your school has recorded in ERA: students, families, grades, payments, attendance, infirmary visits. It is what lets you go back if something goes wrong.</p><p>The page is at <strong>Admin → Backups</strong>, and only administrators see it.</p><div class="info custom-block"><p class="custom-block-title">Not there for you?</p><p>This page only exists when your school is the sole occupant of its installation. Schools hosted by edPage share a server, where one backup would cover every school&#39;s data: yours are taken by edPage rather than from your own space.</p></div><h2 id="every-night-with-nothing-to-do" tabindex="-1">Every night, with nothing to do <a class="header-anchor" href="#every-night-with-nothing-to-do" aria-label="Permalink to &quot;Every night, with nothing to do&quot;">​</a></h2><p>ERA takes an automatic backup every night. The most recent ones are kept and the oldest go on their own, so the server never fills up. How many are kept is shown at the top of the page.</p><p>This is the one that matters most: it covers everything nobody thought to ask for a backup about.</p><h2 id="asking-for-one-yourself" tabindex="-1">Asking for one yourself <a class="header-anchor" href="#asking-for-one-yourself" aria-label="Permalink to &quot;Asking for one yourself&quot;">​</a></h2><p><strong>Back up now</strong> takes one straight away. It is the reflex to have <strong>before anything delicate</strong>: preparing a new school year, a bulk re-enrollment, a large deletion.</p><p>The backup is prepared in the background and appears in the list as soon as it is ready, usually within a minute — the page updates itself, there is no need to reload it.</p><p>Two refusals are possible, both normal:</p><ul><li><strong>A backup is already being prepared.</strong> Wait for it to finish.</li><li><strong>A backup was made less than fifteen minutes ago.</strong> It is still good: use that one.</li></ul><h2 id="downloading-it" tabindex="-1">Downloading it <a class="header-anchor" href="#downloading-it" aria-label="Permalink to &quot;Downloading it&quot;">​</a></h2><p><strong>Download</strong> hands you the file. ERA <strong>asks for your password again</strong> first: the file holds every record the school has, and an open session left unattended is not enough to obtain it.</p><p>Every download is written to the activity log, with who did it and when. The date of the last download is also shown in the list.</p><div class="warning custom-block"><p class="custom-block-title">The file needs the same care as the rest</p><p>Once on your computer it is no longer protected by ERA&#39;s passwords. Keep it the way you would keep the school&#39;s paper register: not in your downloads folder, not on a USB stick lying about, not attached to an email.</p></div><h2 id="what-the-archive-holds-—-and-what-it-does-not" tabindex="-1">What the archive holds — and what it does not <a class="header-anchor" href="#what-the-archive-holds-—-and-what-it-does-not" aria-label="Permalink to &quot;What the archive holds — and what it does not&quot;">​</a></h2><p>It holds <strong>your data</strong>: everything entered into ERA.</p><p>It does <strong>not</strong> hold the application&#39;s technical keys, which stay on the server. That is deliberate: those keys and your data together in one downloadable file would be far more dangerous if the file were ever lost.</p><p>In practice: if the server were lost and everything had to be rebuilt from a downloaded archive, a few technical settings would need redoing — two-factor authentication in particular, which the people using it would set up again. Your data itself would be intact.</p><h2 id="restoring" tabindex="-1">Restoring <a class="header-anchor" href="#restoring" aria-label="Permalink to &quot;Restoring&quot;">​</a></h2><p><strong>Restoring is deliberately not done from this page.</strong> A database cannot be replaced while the application is running on it, and if the operation failed, the tool that should warn you is the one you just interrupted.</p><p>If you need to go back to a backup, contact edPage with the date of the one you want. It is done on the server, with the site closed for as long as it takes.</p><h2 id="deleting-a-backup" tabindex="-1">Deleting a backup <a class="header-anchor" href="#deleting-a-backup" aria-label="Permalink to &quot;Deleting a backup&quot;">​</a></h2><p><strong>Delete</strong> erases the archive from the server for good. Normally there is nothing to do: the oldest ones go by themselves.</p>',25)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
